package com.cvns.security;import java.io.IOException;import org.springframework.security.authentication.UsernamePasswordAuthenticationToken;import org.springframework.security.core.context.SecurityContextHolder;import org.springframework.stereotype.Component;import org.springframework.web.filter.OncePerRequestFilter;import jakarta.servlet.*;import jakarta.servlet.http.*;import lombok.RequiredArgsConstructor;
@Component @RequiredArgsConstructor public class JwtAuthFilter extends OncePerRequestFilter{private final JwtUtils jwt;private final CustomUserDetailsService users;protected void doFilterInternal(HttpServletRequest req,HttpServletResponse res,FilterChain chain)throws ServletException,IOException{String h=req.getHeader("Authorization");if(h!=null&&h.startsWith("Bearer ")&&SecurityContextHolder.getContext().getAuthentication()==null){try{String t=h.substring(7);CustomUserDetails d=(CustomUserDetails)users.loadUserByUsername(jwt.getEmail(t));if(jwt.validate(t,d))SecurityContextHolder.getContext().setAuthentication(new UsernamePasswordAuthenticationToken(d,null,d.getAuthorities()));}catch(Exception ignored){}}chain.doFilter(req,res);}}
